#!/usr/bin/env python3
"""Embeds assets/pic0.png (the tile background) as a C array (src/pic_png.h)."""
import sys
src, dst = sys.argv[1], sys.argv[2]
b = open(src, "rb").read()
rows = [", ".join("0x%02x" % c for c in b[i:i + 16]) for i in range(0, len(b), 16)]
open(dst, "w", newline="\n").write(
    "/* Generated by scripts/gen_pic.py from assets/pic0.png. Do not edit. */\n"
    "#ifndef HB_PIC_PNG_H\n#define HB_PIC_PNG_H\n\n"
    "static const unsigned char hb_pic_png[%d] = {\n    %s\n};\n\n#endif\n"
    % (len(b), ",\n    ".join(rows)))
